SELECT * FROM (SELECT e.event_id,'L:'||s.worker_id case_id,e.activity,e.timestamp FROM (SELECT 'A:'||audit_id||':start' event_id,'Stock Audit Started' activity,started_at timestamp,audit_id source_key FROM warehouse_audit WHERE started_at IS NOT NULL AND (1=1)) e JOIN warehouse_audit s ON s.audit_id=e.source_key WHERE s.worker_id IS NOT NULL UNION ALL SELECT e.event_id,'L:'||s.worker_id case_id,e.activity,e.timestamp FROM (SELECT 'A:'||audit_id||':complete' event_id,'Stock Audit Completed' activity,completed_at timestamp,audit_id source_key FROM warehouse_audit WHERE completed_at IS NOT NULL AND (1=1)) e JOIN warehouse_audit s ON s.audit_id=e.source_key WHERE s.worker_id IS NOT NULL UNION ALL SELECT e.event_id,'L:'||s.worker_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':start' event_id,'Picking Started' activity,started_at timestamp,task_id source_key FROM warehouse_task_history WHERE started_at IS NOT NULL AND (task_code='K')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.worker_id IS NOT NULL UNION ALL SELECT e.event_id,'L:'||s.worker_id case_id,e.activity,e.timestamp FROM (SELECT 'T:'||task_id||':complete' event_id,'Picking Completed' activity,completed_at timestamp,task_id source_key FROM warehouse_task_history WHERE completed_at IS NOT NULL AND (task_code='K')) e JOIN warehouse_task_history s ON s.task_id=e.source_key WHERE s.worker_id IS NOT NULL) ORDER BY case_id,timestamp,event_id;
